-- Viewmodel-recoil comparison variant of cw_anomaly_gsh18. Generated by work/build_vm_recoil.py.
-- Bolt motion measured from the viewmodel: "slide" in anm_shots, 1.617 units, peak frame 1, home frame 3 at 30 fps.

AddCSLuaFile()

SWEP.Base = "cw_anomaly_gsh18"

SWEP.PrintName = "GSh-18 (VM recoil)"

SWEP.LuaViewmodelRecoil = true

SWEP.LuaViewmodelRecoilOverride = false

if CLIENT then
	SWEP.BoltBone = "slide"
	SWEP.BoltShootOffset = Vector(0, 0, 1.617)
	SWEP.BoltBonePositionRecoverySpeed = 25
	SWEP.HoldBoltWhileEmpty = true
	SWEP.DontHoldWhenReloading = true

	killicon.Add("cw_anomaly_gsh18_vmrecoil", "vgui/killicons/tfa_anomaly_gsh18", Color(255, 255, 255))
end

